/bin/bash -lc "python3 - <<'PY'
p='Task.v';s=open(p).read();i=s.index('  - eapply PStep_Pi with (L:=L',s.index('Local Lemma pstep_substitution'));j=s.index('Qed.',i)
s=s[:i]+'''  all: try solve [eapply PStep_CEq; eauto 5 with ni].
  all: try solve [eapply PStep_If; eauto].
  all: try solve [eapply PStep_IfTrue; eauto].
  all: try solve [eapply PStep_IfFalse; eauto].
  all: try solve [eapply CStep_Nleq; eauto 5 with ni].
  all: try solve [rewrite subst_open by (eauto with ni);
                  eapply PStep_AppBeta; simpl in *; eauto].
  all: first [eapply PStep_Pi with (L:=L \\\\u {{x}})
             |eapply PStep_Abs with (L:=L \\\\u {{x}})
             |eapply PStep_SSigma with (L:=L \\\\u {{x}})];
       try solve [eauto 5 with ni].
  all: intros z Hz;
       rewrite <- (@subst_fresh (a_Var_f z) x s) at 1 by (simpl; fsetdec);
       rewrite <- (@subst_fresh (a_Var_f z) x t) at 2 by (simpl; fsetdec);
       rewrite <- "'!subst_open by (eauto with ni);
       first [eapply H0 | eapply H];
       [fsetdec|eapply remove_var_cons; [eassumption|fsetdec]
       |eapply cs_weaken_cons; eassumption].
'"'''+s[j:];open(p,'w').write(s)
PY
timeout 20 make -s"

