/bin/bash -lc "python3 - <<'PY'
p='Task.v';s=open(p).read().replace('''  all: try solve [rewrite subst_open by (eauto with ni);
                  eapply PStep_AppBeta; simpl in *; eauto].''','''  all: try match goal with
  | |- PStep _ _ (a_App _ _ _) (subst_tm _ _ (open_tm_wrt_tm _ _)) =>
